DROP TABLE IF EXISTS `qrt_update`;
CREATE TABLE `qrt_update` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `qid` int(10) NOT NULL,
  `close_comment` varchar(250) CHARACTER SET utf8 DEFAULT NULL,
  `close_date` datetime DEFAULT NULL,
  `status` int(5) NOT NULL,
  `closeby` varchar(250) CHARACTER SET utf8 NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=7698 DEFAULT CHARSET=latin1;

